package com.shengxu.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.core.toolkit.IdWorker; import com.shengxu.entity.*; import com.shengxu.mapper.*; import com.shengxu.service.SunoApiService.ProviderSong;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service
public class TaskProcessor {
 private final MusicTaskMapper tasks; private final MusicLibraryMapper library; private final UserCreditMapper credits; private final CreditRecordMapper records;
 public TaskProcessor(MusicTaskMapper t,MusicLibraryMapper l,UserCreditMapper c,CreditRecordMapper r){tasks=t;library=l;credits=c;records=r;}
 @Transactional public void submitted(MusicTask task,List<ProviderSong> songs){if(songs.isEmpty()){uncertain(task.getId(),"上游未返回歌曲标识，请人工核实");return;}List<String> ids=new ArrayList<>();for(var s:songs){ids.add(s.id());upsert(task,s);}task.setProviderSongIds(String.join(",",ids));task.setSubmitStage("SUBMITTED");task.setStatus("PROCESSING");task.setNextPollAt(LocalDateTime.now().plusSeconds(3));task.setErrorMessage(null);tasks.updateById(task);}
 @Transactional public void uncertain(Long id,String msg){MusicTask t=tasks.selectById(id);t.setSubmitStage("UNCERTAIN");t.setStatus("UNCERTAIN");t.setErrorMessage(msg);t.setNextPollAt(null);tasks.updateById(t);}
 @Transactional public void pollResult(MusicTask task,List<ProviderSong> songs){int success=0,failed=0;for(var s:songs){upsert(task,s);if(s.audioUrl()!=null&&!s.audioUrl().isBlank())success++;else if(isFailed(s.status()))failed++;}int expected=task.getProviderSongIds().split(",").length;task.setPollCount(task.getPollCount()+1);if(success>0&&(success+failed>=expected)){task.setStatus("SUCCESS");task.setFirstAudioUrl(songs.stream().map(ProviderSong::audioUrl).filter(Objects::nonNull).findFirst().orElse(null));task.setNextPollAt(null);}else if(failed>=expected){task.setStatus("FAILED");task.setErrorMessage("音乐生成失败");task.setNextPollAt(null);refund(task);}else{task.setStatus("PROCESSING");task.setNextPollAt(LocalDateTime.now().plusSeconds(Math.min(60,3+task.getPollCount()*2L)));}tasks.updateById(task);}
 private void upsert(MusicTask task,ProviderSong s){MusicLibrary m=library.selectOne(new LambdaQueryWrapper<MusicLibrary>().eq(MusicLibrary::getProviderSongId,s.id()));if(m==null){m=new MusicLibrary();m.setId(IdWorker.getId());m.setTaskId(task.getId());m.setUserId(task.getUserId());m.setProviderSongId(s.id());m.setDeleted(0);m.setFavorite(0);m.setSourceType(task.getSourceType()==null?"GENERATED":task.getSourceType());}m.setStatus(s.audioUrl()!=null&&!s.audioUrl().isBlank()?"SUCCESS":isFailed(s.status())?"FAILED":"PROCESSING");m.setTitle(s.title());m.setAudioUrl(s.audioUrl());m.setCoverUrl(s.coverUrl());m.setLyrics(s.lyrics());m.setStyleTags(s.styleTags());m.setDuration(s.duration());m.setModelVersion(s.model());m.setErrorMessage(s.error());if(library.selectById(m.getId())==null)library.insert(m);else library.updateById(m);}
 private boolean isFailed(String s){return s!=null&&Set.of("failed","error","rejected").contains(s.toLowerCase());}
 private void refund(MusicTask t){String no="TASK:"+t.getId()+":REFUND";if(records.selectCount(new LambdaQueryWrapper<CreditRecord>().eq(CreditRecord::getBusinessNo,no))>0)return;credits.refund(t.getUserId(),t.getCost());UserCredit b=credits.selectOne(new LambdaQueryWrapper<UserCredit>().eq(UserCredit::getUserId,t.getUserId()));CreditRecord r=new CreditRecord();r.setId(IdWorker.getId());r.setUserId(t.getUserId());r.setTaskId(t.getId());r.setRecordType("REFUND");r.setAmount(t.getCost());r.setBalanceAfter(b.getBalance());r.setBusinessNo(no);r.setRemark("生成失败退款");records.insert(r);}
}
